import unittest
from candidate import decode_cyclic, encode_cyclic


class TestDecodeCyclic(unittest.TestCase):
    def test_decode_empty_string(self):
        self.assertEqual(decode_cyclic(""), "")

    def test_decode_single_character(self):
        self.assertEqual(decode_cyclic("a"), "a")

    def test_decode_two_characters(self):
        self.assertEqual(decode_cyclic("ab"), "ab")

    def test_decode_three_characters(self):
        encoded = encode_cyclic("abc")
        self.assertEqual(decode_cyclic(encoded), "abc")

    def test_decode_six_characters(self):
        encoded = encode_cyclic("abcdef")
        self.assertEqual(decode_cyclic(encoded), "abcdef")

    def test_decode_nine_characters(self):
        encoded = encode_cyclic("abcdefghi")
        self.assertEqual(decode_cyclic(encoded), "abcdefghi")

    def test_decode_twelve_characters(self):
        encoded = encode_cyclic("abcdefghijkl")
        self.assertEqual(decode_cyclic(encoded), "abcdefghijkl")

    def test_decode_string_with_remainder_one(self):
        encoded = encode_cyclic("abcdefg")
        self.assertEqual(decode_cyclic(encoded), "abcdefg")

    def test_decode_string_with_remainder_two(self):
        encoded = encode_cyclic("abcdefgh")
        self.assertEqual(decode_cyclic(encoded), "abcdefgh")

    def test_decode_all_same_characters(self):
        encoded = encode_cyclic("aaaaaa")
        self.assertEqual(decode_cyclic(encoded), "aaaaaa")

    def test_decode_repeated_groups(self):
        encoded = encode_cyclic("abcabcabc")
        self.assertEqual(decode_cyclic(encoded), "abcabcabc")

    def test_decode_with_spaces(self):
        encoded = encode_cyclic("a b c d e f")
        self.assertEqual(decode_cyclic(encoded), "a b c d e f")

    def test_decode_with_numbers(self):
        encoded = encode_cyclic("123456789")
        self.assertEqual(decode_cyclic(encoded), "123456789")

    def test_decode_with_special_characters(self):
        encoded = encode_cyclic("!@#$%^&")
        self.assertEqual(decode_cyclic(encoded), "!@#$%^&")

    def test_decode_mixed_characters(self):
        encoded = encode_cyclic("aB3cD5eF7gH9")
        self.assertEqual(decode_cyclic(encoded), "aB3cD5eF7gH9")

    def test_decode_long_string(self):
        original = "x" * 100
        encoded = encode_cyclic(original)
        self.assertEqual(decode_cyclic(encoded), original)

    def test_decode_known_encoded_value(self):
        self.assertEqual(decode_cyclic("bca"), "abc")

    def test_decode_known_encoded_value_two_groups(self):
        encoded = encode_cyclic("abcdef")
        self.assertEqual(encoded, "bcaefd")
        self.assertEqual(decode_cyclic("bcaefd"), "abcdef")

    def test_decode_roundtrip_multiple_times(self):
        original = "hello world test"
        encoded = encode_cyclic(original)
        decoded = decode_cyclic(encoded)
        self.assertEqual(decoded, original)

    def test_decode_idempotent_of_encode_applied_thrice(self):
        s = "abcdef"
        self.assertEqual(encode_cyclic(encode_cyclic(encode_cyclic(s))), s)

    def test_decode_returns_string_type(self):
        result = decode_cyclic(encode_cyclic("test"))
        self.assertIsInstance(result, str)

    def test_decode_with_unicode_characters(self):
        encoded = encode_cyclic("héllo")
        self.assertEqual(decode_cyclic(encoded), "héllo")

    def test_decode_with_newline_and_tab(self):
        original = "ab\ncd\tef"
        encoded = encode_cyclic(original)
        self.assertEqual(decode_cyclic(encoded), original)


if __name__ == '__main__':
    unittest.main()
